constexpr int factorial(int n) {
    return (n <= 1) ? 1 : n * factorial(n - 1);
}

constexpr int FACT_5 = factorial(5); // Evaluated at compile time (120)

// Requires compile-time constant size
float data_buffer[FACT_5];

class Constants {
public:
    // Defined inside class, compile-time constant
    static constexpr int DEFAULT_SIZE = 10;
    static constexpr int getSquare(int x) {
        return x * x;
    }
};

constexpr int MAX_SQ = Constants::getSquare(Constants::DEFAULT_SIZE);
int storage[MAX_SQ]; // Array size 100
